/**
 * @method
 * @name scwin.tx_fn_FrnIntDecl
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_FrnIntDecl = async function () {
    const sbmOptions = {
        id: "tx_fn_FrnIntDecl",
        method: "post",
        action: "/event/event.do",
        ref: "dma_FrnIntDeclReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf90011.tx_fn_FrnIntDecl" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

