/**
 * @method
 * @name scwin.popupBatchApplExcelUpload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.popupBatchApplExcelUpload = function () {
    /* sdd-asis-lifecycle:begin fn_popupBatchApplExcelUpload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const width = 1040;
    const height = 520;
    const mtWidth = document.body.clientWidth;
    const mtHeight = document.body.clientHeight;
    const scX = 0;
    const scY = 0;
    const popX = scX + (mtWidth - width) / 2;
    const popY = scY + (mtHeight - height) / 2;
